import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Locale;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        StringTokenizer tokenizer = new StringTokenizer(line);
        int n = Integer.parseInt(tokenizer.nextToken());
        double d = Double.parseDouble(tokenizer.nextToken());

        double[] p = new double[n + 1];
        double[] c = new double[n + 1];

        for (int i = 0; i < n; i++) {
            line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            tokenizer = new StringTokenizer(line);
            p[i] = Double.parseDouble(tokenizer.nextToken());
            c[i] = Double.parseDouble(tokenizer.nextToken());
        }

        p[n] = d;

        double[] dp = new double[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = Double.POSITIVE_INFINITY;
        }
        dp[0] = 0.0;

        for (int j = 1; j <= n; j++) {
            for (int i = 0; i < j; i++) {
                double dist = p[j] - p[i];
                double time = (dist * dist) / c[i];
                if (dp[i] + time < dp[j]) {
                    dp[j] = dp[i] + time;
                }
            }
        }

        System.out.printf(Locale.US, "%.3f\n", dp[n]);
    }
}
